import{planeBoardFrame,planeDisembarkFrame,PLANE_DISEMBARK_DURATION}from'./plane-support.js';import{sampleFlightPhase,FLIGHT_PHASES}from'./flight-motion.js';
// Isolated physical driver only. It never loads, switches or disposes a game room.
// Future host integration must wrap the reviewed manager contract; this is not that contract.
export function createFlightPrototype({from={x:-4.6,y:.05,z:-.75,yaw:Math.PI/2},motionFree=false}={}){const origin={...from};let state=motionFree?'arrived':'boarding',time=0,phase=0,paused=false,reversing=false;const board={},motion={};
 function tick(dt){if(paused||!Number.isFinite(dt)||dt<=0||['arrived','cancelled','seated'].includes(state))return;let left=Math.min(dt,.05);if(reversing){time=Math.max(0,time-left);if(time===0){if(state==='unseal'){state='boarding';time=8;}else{state='cancelled';reversing=false;}}return;}
 while(left>1e-10){const duration=state==='boarding'?8:state==='dismount'?PLANE_DISEMBARK_DURATION:FLIGHT_PHASES[phase].duration,step=Math.min(left,duration-time);time+=step;left-=step;if(time>=duration-1e-9){time=0;if(state==='boarding'){state='seated';break;}if(state==='dismount'){state='arrived';break;}phase++;if(phase===FLIGHT_PHASES.length)state='dismount';}}
 }
 function sample(){if(state==='boarding'||state==='cancelled'){planeBoardFrame(origin,state==='cancelled'?0:time,board);return{...board,plane:{x:-5,y:0,z:8,yaw:0,pitch:0,roll:0},space:'airport'};}if(state==='dismount'||state==='arrived'){planeDisembarkFrame(state==='arrived'?PLANE_DISEMBARK_DURATION:time,board);return{...board,plane:{x:-5,y:0,z:8,yaw:0,pitch:0,roll:0},space:'airport'};}planeBoardFrame(origin,8,board);if(state==='unseal'){sampleFlightPhase('seal',time,motion);return{...motion,actor:board.actor};}if(state==='seated')return{...board,plane:{x:-5,y:0,z:8,yaw:0,pitch:0,roll:0},space:'airport'};sampleFlightPhase(FLIGHT_PHASES[phase].name,time,motion);return{...motion,actor:board.actor};}
 return{tick,sample,start(){if(state!=='seated'||paused)return false;state='journey';phase=0;time=0;return true;},reverse(){if(state==='boarding'){reversing=true;return true;}if(state==='journey'&&phase===0){state='unseal';reversing=true;return true;}if(state==='seated'){state='boarding';time=8;reversing=true;return true;}return false;},pause(){paused=true;},resume(){paused=false;},snapshot(){return{state,time,phase:state==='journey'?FLIGHT_PHASES[phase].name:null,paused,reversing};},get done(){return state==='arrived'||state==='cancelled';}};
}
